//  WordPieceTokenizerGoldenTests.swift
//  MealRecognizeTests
//

import XCTest
@testable import MealRecognize

/// Compares `WordPieceTokenizer` with the Hugging Face tokenizer of the checkpoint.
/// `Resources/golden_tokenizer.json` is generated by `tools/make_golden_tokenizer.py`; regenerate it
/// when the vocabulary or the tokenizer changes.
final class WordPieceTokenizerGoldenTests: XCTestCase {

    private struct Golden: Decodable {
        struct Case: Decodable {
            let text: String
            let input_ids: [Int32]
            let attention_mask: [Int32]
        }
        let max_length: Int
        let cases: [Case]
    }

    func testMatchesHuggingFaceTokenizer() throws {
        let tokenizer = try WordPieceTokenizer(vocabularyURL: try vocabularyURL())
        let goldenURL = try XCTUnwrap(Bundle.module.url(forResource: "golden_tokenizer", withExtension: "json"))
        let golden = try JSONDecoder().decode(Golden.self, from: Data(contentsOf: goldenURL))
        XCTAssertFalse(golden.cases.isEmpty)

        var failures = 0
        for expected in golden.cases {
            // The app lowercases Russian input before tokenizing; the golden ids are computed the same way.
            let encoding = try tokenizer.encode(
                Language.russian.lowercasesInput ? expected.text.lowercased() : expected.text,
                maxLength: golden.max_length
            )
            if encoding.inputIds != expected.input_ids || encoding.attentionMask != expected.attention_mask {
                failures += 1
                XCTFail("Mismatch for \(expected.text.debugDescription)\n"
                        + "expected \(expected.input_ids.prefix(24))…\n"
                        + "got      \(encoding.inputIds.prefix(24))…")
            }
        }
        XCTAssertEqual(failures, 0)
    }

    private func vocabularyURL() throws -> URL {
        let language = Language.russian
        return try XCTUnwrap(language.resourceURL(name: language.vocabularyName, withExtension: "txt"))
    }
}
